/* artifact card */
.afc-prev{padding:16px 16px 0;background:var(--chip)}
.afc-doc{padding:16px 18px 18px;background:var(--panel);border:1px solid var(--line);border-bottom:0;height:172px;overflow:hidden}
.afc-h{font-weight:600;font-size:14px}
.afc-p{margin-top:4px;font-size:12px;line-height:1.5;color:var(--text-dim)}
.afc-bars{display:flex;align-items:flex-end;gap:6px;height:56px;margin:14px 0 12px}
.afc-bars i{flex:1;height:10%;background:var(--accent);opacity:.85;transition:height .6s var(--ease)}
.afc-bars i:nth-child(even){opacity:.45}
.afc-ln i{display:block;height:6px;margin-top:6px;background:var(--chip)}
.afc-meta{display:flex;align-items:center;gap:12px;padding:12px 16px;border-top:1px solid var(--line)}
.afc-ic{width:32px;height:32px;flex:none;display:grid;place-items:center;background:var(--chip)}
.afc-mt{flex:1;min-width:0;display:flex;flex-direction:column}
.afc-mt .t{font-weight:600;font-size:14px}
.afc-vers{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 16px 12px;border-top:1px solid var(--line)}
.afc-tabs{display:flex;gap:4px}
.afc-tabs button{padding:4px 10px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);transition:color .2s,background .2s}
.afc-tabs button:hover{color:var(--text);background:var(--chip)}
.afc-tabs button.on{color:var(--text);background:var(--chip)}

/* ---------- artifact card ---------- */
{
  const bars = $$('#afc-bars i'), tabs = $$('#afc-tabs button'), link = $('#afc-link');
  const V = [
    { p:'First pass at churn by month, sources still to check.', b:[30,38,44,40,36,34], sub:'v1, edited yesterday', note:'First draft' },
    { p:'Churn rose in July, the spike lines up with the pricing change.', b:[30,38,82,56,44,40], sub:'v2, edited 1 hour ago', note:'Added the July spike' },
    { p:'Churn rose in July, then settled once onboarding emails went out.', b:[30,38,82,52,34,26], sub:'v3, edited 2 min ago', note:'Final, with your fixes' }
  ];
  let cur = 2;
  function show(i, quiet){
    cur = i; const v = V[i];
    tabs.forEach((t, k) => t.classList.toggle('on', k === i));
    swapText($('#afc-p'), v.p); swapText($('#afc-sub'), v.sub); swapText($('#afc-note'), v.note);
    bars.forEach((b, k) => setTimeout(() => b.style.height = v.b[k] + '%', k * 50));
    if (!quiet) Sound.play('tab');
  }
  tabs.forEach((t, i) => t.addEventListener('click', () => i !== cur && show(i)));
  link.addEventListener('click', () => {
    Sound.play('done'); swapText($('#afc-sub'), 'Link copied');
    setTimeout(() => swapText($('#afc-sub'), V[cur].sub), 1400);
  });
  function play(){ bars.forEach(b => b.style.height = '10%'); setTimeout(() => show(2, true), 120); ambient('c108', 'pop'); }
  $('#afc-play').addEventListener('click', () => { Sound.play('tab'); play(); });
  whenSeen($('#c108'), play);
}
